function wireCareers(){
const form=document.getElementById('careerForm');if(!form)return;
const j=t.careers;
form.addEventListener('submit',e=>{
 e.preventDefault();
 if(!form.reportValidity())return;
 const read=id=>document.getElementById(id).value.trim();
 const idx=id=>Number(document.getElementById(id).value);
 const name=read('careerName'),phone=read('careerPhone');
 if(!name||!phone||!document.getElementById('careerAck').checked)return;
 const lines=[j.waIntro,'',
  j.waLabels[0]+': '+name,
  j.waLabels[1]+': '+phone,
  j.waLabels[2]+': '+j.jobs[idx('careerRole')][0],
  j.waLabels[3]+': '+j.expChoices[idx('careerExp')],
  j.waLabels[4]+': '+j.scheduleChoices[idx('careerSchedule')]];
 const note=read('careerComment');if(note)lines.push(j.waLabels[5]+': '+note);
 window.open(wapp(lines.join('\n')),'_blank','noopener,noreferrer');
});
}

