document.getElementById('langSelect').addEventListener('change',e=>{const target=e.target.value;try{localStorage.setItem('acproLang',target)}catch(x){}const u=new URL(location.href);if(target==='ru')u.searchParams.delete('lang');else u.searchParams.set('lang',target);location.assign(u.href)});
const toggle=document.getElementById('navToggle'),nav=document.getElementById('mainNav');
toggle.addEventListener('click',()=>{let open=nav.classList.toggle('active');toggle.setAttribute('aria-expanded',String(open))});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('active');toggle.setAttribute('aria-expanded','false')}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('active');toggle.setAttribute('aria-expanded','false')}});
const heading=document.querySelector('h1')?.textContent||'ASTANA CLEANING PRO';
document.title=heading+' | ASTANA CLEANING PRO';
const descr=document.querySelector('main p')?.textContent||t.footer;
document.querySelector('meta[name="description"]')?.setAttribute('content',descr);
document.querySelector('meta[property="og:title"]')?.setAttribute('content',document.title);
document.querySelector('meta[property="og:description"]')?.setAttribute('content',descr);
const canonical=document.createElement('link');canonical.rel='canonical';canonical.href=new URL(pages[current]+(lang==='ru'?'':'?lang='+lang),location.href).href;document.head.appendChild(canonical);
for(const code of known){const alt=document.createElement('link');alt.rel='alternate';alt.hreflang=code;alt.href=new URL(pages[current]+(code==='ru'?'':'?lang='+code),location.href).href;document.head.appendChild(alt)}
